#!/bin/bash
# =============================================================================
# Komodo Flutter Wallet - Project Cleanup
#
# Removes regenerable build artifacts and downloaded binaries. Everything
# deleted here is recreated by `./build_macos.sh` on the next run — except
# the opt-in items (see below), which are never essential but are NOT
# replaced by the build script.
#
# Usage:
#   ./cleanup.sh [light|full] [options]
#
# Modes:
#   light (default)  Flutter/Xcode build caches + ephemeral files.
#                    Fully regenerated by the next `./build_macos.sh` in seconds
#                    to minutes. No confirmation required.
#
#   full             light + CocoaPods, prebuilt KDF binaries (all platforms),
#                    Cargo target/, and the web wasm bundle.
#                    All re-downloaded (or recompiled) by the next
#                    `./build_macos.sh`, but the KDF re-fetch and any local
#                    Rust compilation make the next build MUCH slower.
#                    Asks for confirmation unless --yes is passed.
#
# Options:
#   --dry-run        List what would be deleted (with sizes); delete nothing.
#   -y, --yes        Skip confirmation prompts.
#   --dart-sdk       ALSO delete sdk/dart-sdk (~625 MB). It is unreferenced by
#                    the build, but build_macos.sh does NOT restore it —
#                    opt-in only for that reason.
#   --logs           ALSO delete ~/Documents/dragon_logs (application logs).
#                    User data; nothing restores it.
#   -h, --help       Show this help.
#
# Examples:
#   ./cleanup.sh                    # light clean (same as: ./cleanup.sh light)
#   ./cleanup.sh --dry-run full     # preview a full clean
#   ./cleanup.sh full -y            # full clean without prompting
#   ./cleanup.sh full --dart-sdk    # full clean + the unused vendored Dart SDK
# =============================================================================
set -euo pipefail

# -----------------------------------------------------------------------------
# Resolve project root (the dir containing this script) and sanity-check it.
# -----------------------------------------------------------------------------
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cd "$SCRIPT_DIR"

if [ ! -f "pubspec.yaml" ] || [ ! -f "build_macos.sh" ]; then
  echo "Error: this does not look like the project root (missing pubspec.yaml" \
       "or build_macos.sh next to cleanup.sh)." >&2
  exit 1
fi

MODE="light"
DRY_RUN=false
ASSUME_YES=false
CLEAN_DART_SDK=false
CLEAN_LOGS=false

for arg in "$@"; do
  case "$arg" in
    light)      MODE="light" ;;
    full)       MODE="full" ;;
    --dry-run)  DRY_RUN=true ;;
    -y|--yes)   ASSUME_YES=true ;;
    --dart-sdk) CLEAN_DART_SDK=true ;;
    --logs)     CLEAN_LOGS=true ;;
    -h|--help)  grep -E '^# (Usage:|Modes:|  light|  full|Options:|  --|  -y|  -h|Examples:|  \./cleanup)' "$0" | sed 's/^# \{0,1\}//'; exit 0 ;;
    *)
      echo "Unknown argument: $arg (use --help for usage)" >&2
      exit 1
      ;;
  esac
done

# -----------------------------------------------------------------------------
# Helpers
# -----------------------------------------------------------------------------
FREED_BYTES=0

# size_mb <path>
size_mb() {
  [ -e "$1" ] && du -sk "$1" 2>/dev/null | awk '{print int($1 / 1024)}' || echo 0
}

# remove <label> <path>...
# Tolerant deletion: retries once on transient "Directory not empty" races
# (e.g. the app or kdf helper still flushing files while shutting down) and
# reports rather than aborts the whole cleanup.
remove() {
  local label="$1"; shift
  local total_mb=0 any=false
  for p in "$@"; do
    if [ -e "$p" ]; then
      any=true
      total_mb=$(( total_mb + $(size_mb "$p") ))
    fi
  done
  if [ "$any" = false ]; then
    printf '  [skip]     %-46s (nothing to delete)\n' "$label"
    return 0
  fi
  if [ "$DRY_RUN" = true ]; then
    printf '  [dry-run]  %-46s ~%s MB\n' "$label" "$total_mb"
    return 0
  fi
  local failed=false
  for p in "$@"; do
    [ -e "$p" ] || continue
    if ! rm -rf "$p" 2>/dev/null; then
      sleep 2
      if ! rm -rf "$p" 2>/dev/null; then
        failed=true
        printf '  [WARNING]  could not fully delete %s (in use?)\n' "$p" >&2
      fi
    fi
  done
  if [ "$failed" = false ]; then
    FREED_BYTES=$(( FREED_BYTES + total_mb * 1024 * 1024 ))
    printf '  [deleted]  %-46s ~%s MB\n' "$label" "$total_mb"
  fi
}

confirm() {
  if [ "$ASSUME_YES" = true ] || [ "$DRY_RUN" = true ]; then return 0; fi
  printf 'Proceed? [y/N] '
  read -r reply
  case "$reply" in
    y|Y|yes|YES) return 0 ;;
    *) echo "Aborted."; exit 0 ;;
  esac
}

# -----------------------------------------------------------------------------
# Preflight
# -----------------------------------------------------------------------------
MODE_SUFFIX=""
[ "$DRY_RUN" = true ] && MODE_SUFFIX=", dry-run"
echo "=== Komodo Flutter Wallet cleanup (mode: $MODE$MODE_SUFFIX) ==="

# Refuse to yank the build directory out from under a running app or the KDF
# helper it spawned — deletion races with their file handles and the next
# launch could behave oddly.
if pgrep -f "Komodo Flutter Wallet.app" >/dev/null 2>&1; then
  echo "WARNING: 'Komodo Flutter Wallet' (or its kdf helper) is currently running."
  if [ "$ASSUME_YES" = true ]; then
    echo "  --yes passed; continuing anyway (you may want to quit the app first)."
  else
    echo "  Quit the app and re-run, or pass --yes to continue regardless."
    exit 1
  fi
fi

# -----------------------------------------------------------------------------
# LIGHT — everything below is regenerated trivially by ./build_macos.sh
# (flutter pub get / flutter build / pod install).
# -----------------------------------------------------------------------------
echo ""
echo "[light] Flutter & Xcode build caches"
remove "build/ (flutter + xcode output)"        "build"
remove ".dart_tool/ (pub resolution)"           ".dart_tool"
remove ".flutter-plugins*"                      ".flutter-plugins" ".flutter-plugins-dependencies"
remove "macos/Flutter/ephemeral/"               "macos/Flutter/ephemeral"

# Housekeeping: Finder metadata (harmless, keeps the tree tidy)
if [ "$DRY_RUN" = true ]; then
  n=$(find . -name ".DS_Store" -not -path "./sdk/dart-sdk/*" -not -path "./build/*" 2>/dev/null | wc -l | tr -d ' ')
  printf '  [dry-run]  %-46s %s files\n' ".DS_Store files" "$n"
else
  n=$(find . -name ".DS_Store" -not -path "./sdk/dart-sdk/*" -not -path "./build/*" -delete -print 2>/dev/null | wc -l | tr -d ' ')
  printf '  [deleted]  %-46s %s files\n' ".DS_Store files" "$n"
fi

# -----------------------------------------------------------------------------
# FULL — regenerated by ./build_macos.sh, but expensively (re-download of the
# prebuilt KDF binaries and/or a local Rust compilation of libkdf).
# -----------------------------------------------------------------------------
if [ "$MODE" = "full" ]; then
  echo ""
  echo "[full] CocoaPods & downloaded/compiled native artifacts"
  echo "  NOTE: the next ./build_macos.sh will re-download the KDF binaries and"
  echo "        recompile libkdf if no prebuilt binary is available. This can"
  echo "        take a long time."

  confirm

  remove "macos/Pods/ (recreated by pod install)"  "macos/Pods"
  remove "Cargo target/ (rust build cache)"       "sdk/komodo-defi-framework/target"

  # Prebuilt libkdf binaries fetched by komodo_wallet_build_transformer,
  # identified by their .api_last_updated_* download stamps.
  remove "KDF binaries: framework bin/ dirs" \
    "sdk/komodo-defi-sdk/packages/komodo_defi_framework/bin" \
    "sdk/komodo-defi-sdk/packages/komodo_defi_framework/macos/bin" \
    "sdk/komodo-defi-sdk/packages/komodo_defi_framework/linux/bin" \
    "sdk/komodo-defi-sdk/packages/komodo_defi_framework/windows/bin"
  remove "KDF static libs: ios + android" \
    "sdk/komodo-defi-sdk/packages/komodo_defi_framework/ios/libkdf.a" \
    "sdk/komodo-defi-sdk/packages/komodo_defi_framework/android/app/src/main/cpp/libs"
  remove "KDF wasm: web bundles" \
    "sdk/komodo-defi-sdk/packages/komodo_defi_framework/web/kdf" \
    "web/kdf/kdf/bin"

  # Download stamps so the transformer does not think the (now deleted)
  # binaries are still current.
  remove "transformer download stamps" $(find sdk/komodo-defi-sdk/packages/komodo_defi_framework -name ".api_last_updated_*" 2>/dev/null)
fi

# -----------------------------------------------------------------------------
# OPT-IN — NOT restored by build_macos.sh. Only ever removed when explicitly
# requested.
# -----------------------------------------------------------------------------
if [ "$CLEAN_DART_SDK" = true ]; then
  echo ""
  echo "[opt-in] sdk/dart-sdk (~625 MB)"
  echo "  This vendored Dart SDK is not referenced by the build, but nothing"
  echo "  will re-download it. Intended for one-time reclamation of disk space."
  confirm
  remove "sdk/dart-sdk/ (unreferenced toolchain)" "sdk/dart-sdk"
fi

if [ "$CLEAN_LOGS" = true ]; then
  echo ""
  echo "[opt-in] application logs"
  confirm
  remove "~/Documents/dragon_logs (app logs)" "$HOME/Documents/dragon_logs"
fi

# -----------------------------------------------------------------------------
# Summary
# -----------------------------------------------------------------------------
echo ""
if [ "$DRY_RUN" = true ]; then
  echo "Dry run complete — nothing was deleted."
else
  if [ "$FREED_BYTES" -ge 1073741824 ]; then
    printf "Cleanup complete. Freed ~%.1f GB\n" "$(echo "scale=2; $FREED_BYTES / 1073741824" | bc)"
  else
    printf "Cleanup complete. Freed ~%s MB\n" "$(( FREED_BYTES / 1024 / 1024 ))"
  fi
  echo "Run ./build_macos.sh to rebuild."
fi
